@staticmethod
def _repeated_patterns(tokens: Sequence[int]) -> dict[tuple[int, int], int]:
    """Returns the top 3 most frequent adjacent token pairs with their counts."""
    if len(tokens) < 2:
        return {}
    counter = Counter(zip(tokens, tokens[1:]))
    return dict(counter.most_common(3))

